// --- Mock order database ---------------------------------------------
// Replace this block with a real DB query or HTTP Request node call to
// your order-management system / ecommerce API in production.
const orders = {
  ORD1001: { status: 'Delayed', expectedDelivery: '2026-09-20', reason: 'Courier hub congestion in transit city' },
  ORD1002: { status: 'On Time', expectedDelivery: '2026-09-16', reason: null },
  ORD1003: { status: 'Delayed', expectedDelivery: '2026-09-22', reason: 'Item held at customs' },
  ORD1004: { status: 'Out for Delivery', expectedDelivery: '2026-09-15', reason: null },
  ORD1005: { status: 'On Time', expectedDelivery: '2026-09-18', reason: null }
};

// In a Code Tool the argument the agent passes is exposed as the top-level
// variable 'query'. With a manual input schema it is the validated object
// { orderId: '...' }; without one it can arrive as a plain string.
let raw;
if (query && typeof query === 'object') {
  raw = query.orderId;
} else if (typeof query === 'string') {
  try {
    const parsed = JSON.parse(query);
    raw = (parsed && parsed.orderId) ? parsed.orderId : query;
  } catch (e) {
    raw = query;
  }
}

if (!raw) {
  return JSON.stringify({ error: 'No orderId provided.' });
}

const orderId = String(raw).trim().toUpperCase();
const order = orders[orderId];

if (!order) {
  return JSON.stringify({
    orderId,
    found: false,
    message: 'No order found with this ID. Ask the customer to double-check it.'
  });
}

return JSON.stringify({
  orderId,
  found: true,
  status: order.status,
  expectedDelivery: order.expectedDelivery,
  delayReason: order.reason
});
